def similar_command(cmd: str) -> Optional[str]:
    # The original clap output suggests these obvious near misses.  Keep the
    # logic small and deterministic.
    def lev(a: str, b: str) -> int:
        prev = list(range(len(b) + 1))
        for i, ca in enumerate(a, 1):
            cur = [i]
            for j, cb in enumerate(b, 1):
                cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
            prev = cur
        return prev[-1]
    best = min(["local", "server", "help"], key=lambda c: lev(cmd, c))
    if lev(cmd, best) <= 2 or cmd.startswith(best) or best.startswith(cmd.strip("-")):
        return best
    return None


def parse_top(argv: List[str]) -> None:
    p = prog_name()
    if not argv:
        sys.stderr.write(top_help())
        raise SystemExit(2)
    first = argv[0]
    if first in ("-h", "--help"):
        sys.stdout.write(top_help())
        return
    if first in ("-V", "--version"):
        sys.stdout.write(VERSION + "\n")
        return
    if first == "help":
        rest = argv[1:]
        if not rest:
            sys.stdout.write(top_help())
            return
        if rest[0] == "local":
            if len(rest) > 1:
                die2(f"unrecognized subcommand '{rest[1]}'", usage=f"{p} local [OPTIONS] --to <TO> <LOCAL_PORT>")
            sys.stdout.write(local_help())
            return
        if rest[0] == "server":
            if len(rest) > 1:
                die2(f"unrecognized subcommand '{rest[1]}'", usage=f"{p} server [OPTIONS]")
            sys.stdout.write(server_help())
            return
        if rest[0] == "help":
            sys.stdout.write(help_help())
            return
        die2(f"unrecognized subcommand '{rest[0]}'", usage=f"{p} <COMMAND>")
    if first == "--":
        if len(argv) > 1:
            unknown = argv[1]
            sim = similar_command(unknown)
            msg = f"unrecognized subcommand '{unknown}'"
            sys.stderr.write(f"error: {msg}\n")
            if sim:
                sys.stderr.write(f"\n  tip: a similar subcommand exists: '{sim}'\n")
                sys.stderr.write(f"  tip: to pass '{unknown}' as a value, use '{p} -- {unknown}'\n")
            sys.stderr.write(f"\nUsage: {p} <COMMAND>\n\nFor more information, try '--help'.\n")
            raise SystemExit(2)
        die2("a subcommand is required", usage=f"{p} <COMMAND>")
    if first == "local":
        parse_local(argv[1:])
        return
    if first == "server":
        parse_server(argv[1:])
        return
    if first.startswith("-"):
        die2(f"unexpected argument '{first}' found", usage=f"{p} <COMMAND>")
    # Unknown subcommand, with observed clap suggestions for close matches.
    sim = similar_command(first)
    sys.stderr.write(f"error: unrecognized subcommand '{first}'\n")
    if sim:
        sys.stderr.write(f"\n  tip: a similar subcommand exists: '{sim}'\n")
        sys.stderr.write(f"  tip: to pass '{first}' as a value, use '{p} -- {first}'\n")
    sys.stderr.write(f"\nUsage: {p} <COMMAND>\n\nFor more information, try '--help'.\n")
    raise SystemExit(2)


def main() -> None:
    # Make SIGTERM (as used by `timeout`) terminate promptly without a Python
    # traceback.  The default also exits; this keeps behavior predictable.
    signal.signal(signal.SIGTERM, lambda signum, frame: raise_system_exit_143())
    parse_top(sys.argv[1:])


def raise_system_exit_143() -> None:
    raise SystemExit(143)


if __name__ == "__main__":
    try:
        main()
    except BrokenPipeError:
        try:
            sys.stdout.close()
        finally:
            raise SystemExit(1)
