def eprint(s: str = "") -> None:
    sys.stderr.write(s)
    if not s.endswith("\n"):
        sys.stderr.write("\n")
    sys.stderr.flush()


def die2(message: str, usage: Optional[str] = None, tip: Optional[str] = None) -> None:
    sys.stderr.write(f"error: {message}\n")
    if tip:
        sys.stderr.write(f"\n  tip: {tip}\n")
    if usage:
        sys.stderr.write(f"\nUsage: {usage}\n")
    sys.stderr.write("\nFor more information, try '--help'.\n")
    sys.stderr.flush()
    raise SystemExit(2)


def die_runtime(message: str, cause: Optional[str] = None) -> None:
    sys.stderr.write(f"Error: {message}\n")
    if cause is not None:
        sys.stderr.write(f"\nCaused by:\n    {cause}\n")
    sys.stderr.flush()
    raise SystemExit(1)


def port_parse_error(value: str, label: str) -> None:
    # Rust's u16 parser reports negative values as out-of-range when they are
    # forced as a value (e.g. --port=-1 or after --), and non-digits as an
    # invalid digit.
    try:
        n = int(value, 10)
    except Exception:
        die2(f"invalid value '{value}' for '{label}': invalid digit found in string")
    if n < 0 or n > 65535:
        die2(f"invalid value '{value}' for '{label}': {value} is not in 0..=65535")
    return None


def parse_u16(value: str, label: str) -> int:
    port_parse_error(value, label)
    return int(value, 10)


def validate_ip(value: str, opt_label: str) -> str:
    try:
        ipaddress.ip_address(value)
        return value
    except Exception:
        die2(f"invalid value '{value}' for '{opt_label}': invalid IP address syntax")


# ---------------------------------------------------------------------------
# tracing-subscriber-style logging


def _level_enabled(level: str) -> bool:
    rust_log = os.environ.get("RUST_LOG")
    if not rust_log:
        return True
    first = rust_log.split(",", 1)[0].strip().lower()
    if first.startswith("error"):
        return level == "ERROR"
    if first.startswith("warn"):
        return level in ("WARN", "ERROR")
    # debug/trace/info all show the info/warn messages this tool emits.
    return True


def _ts() -> str:
    return _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")


def log(level: str, target: str, message: str, *, span: Optional[Tuple[str, Dict[str, Any]]] = None,
        fields: Optional[Dict[str, Any]] = None) -> None:
    if not _level_enabled(level):
        return
    no_color = os.environ.get("NO_COLOR") is not None
    fields = fields or {}
    if no_color:
        parts = [_ts(), f"{level:>5}"]
        if span:
            name, sf = span
            sfields = " ".join(f"{k}={v}" for k, v in sf.items())
            # tracing formats span fields as control{addr=...}:
            if sfields:
                parts.append(f"{name}" + "{" + sfields + "}:")
            else:
                parts.append(f"{name}:")
        parts.append(f"{target}:")
        parts.append(message)
        for k, v in fields.items():
            parts.append(f"{k}={v}")
        print(" ".join(parts), flush=True)
        return

    color = {"INFO": "\x1b[32m", "WARN": "\x1b[33m", "ERROR": "\x1b[31m"}.get(level, "")
    out = f"\x1b[2m{_ts()}\x1b[0m {color}{level:>5}\x1b[0m "
    if span:
        name, sf = span
        out += f"\x1b[1m{name}\x1b[0m\x1b[1m{{\x1b[0m"
        first = True
        for k, v in sf.items():
            if not first:
                out += " "
            first = False
            out += f"\x1b[3m{k}\x1b[0m\x1b[2m=\x1b[0m{v}"
        out += f"\x1b[1m}}\x1b[0m\x1b[2m:\x1b[0m "
    out += f"\x1b[2m{target}\x1b[0m\x1b[2m:\x1b[0m {message}"
    for k, v in fields.items():
        out += f" \x1b[3m{k}\x1b[0m\x1b[2m=\x1b[0m{v}"
    print(out, flush=True)


# ---------------------------------------------------------------------------
# JSON-line protocol helpers used between this reimplementation's client/server


def send_json(sock: socket.socket, obj: Dict[str, Any], lock: Optional[threading.Lock] = None) -> None:
    data = (json.dumps(obj, separators=(",", ":")) + "\n").encode("utf-8")
    if lock:
        with lock:
            sock.sendall(data)
    else:
        sock.sendall(data)


def recv_line(sock: socket.socket, limit: int = 1024 * 1024) -> Optional[bytes]:
    buf = bytearray()
    while True:
        try:
            b = sock.recv(1)
        except InterruptedError:
            continue
        if not b:
            if not buf:
                return None
            return bytes(buf)
        buf += b
        if b == b"\n":
            return bytes(buf)
        if len(buf) > limit:
            raise ValueError("line too long")


def recv_json(sock: socket.socket) -> Optional[Dict[str, Any]]:
    line = recv_line(sock)
    if line is None:
        return None
    try:
        obj = json.loads(line.decode("utf-8"))
        if isinstance(obj, dict):
            return obj
    except Exception:
        pass
    return {"type": "invalid"}


def socket_family_for_ip(ip: str) -> int:
    try:
        return socket.AF_INET6 if ipaddress.ip_address(ip).version == 6 else socket.AF_INET
    except Exception:
        return socket.AF_INET


def bind_listener(ip: str, port: int) -> socket.socket:
    fam = socket_family_for_ip(ip)
    s = socket.socket(fam, socket.SOCK_STREAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    s.bind((ip, port))
    s.listen(128)
    return s


def format_os_error(e: BaseException) -> str:
    if isinstance(e, ConnectionRefusedError):
        return "Connection refused (os error 111)"
    if isinstance(e, ConnectionResetError):
        return "Connection reset by peer (os error 104)"
    if isinstance(e, socket.gaierror):
        return "failed to lookup address information: Name or service not known"
    if isinstance(e, TimeoutError) or isinstance(e, socket.timeout):
        return "operation timed out"
    if isinstance(e, OSError):
        if e.errno == errno.EADDRINUSE:
            return "Address already in use (os error 98)"
        if e.errno == errno.EACCES:
            return "Permission denied (os error 13)"
        if e.errno == errno.ECONNREFUSED:
            return "Connection refused (os error 111)"
        if e.errno == errno.ECONNRESET:
            return "Connection reset by peer (os error 104)"
        if e.errno is not None and e.strerror:
            return f"{e.strerror} (os error {e.errno})"
    return str(e)


# ---------------------------------------------------------------------------
# Server implementation


class PendingProxy:
    def __init__(self, external: socket.socket, ext_addr: Tuple[Any, ...], tunnel: "Tunnel") -> None:
        self.external = external
        self.ext_addr = ext_addr
        self.tunnel = tunnel
        self.created = time.time()


class Tunnel:
    def __init__(self, port: int, host: str, listener: socket.socket, control: socket.socket,
                 control_addr: Tuple[Any, ...], control_lock: threading.Lock, server: "BoreServer") -> None:
        self.port = port
        self.host = host
        self.listener = listener
        self.control = control
        self.control_addr = control_addr
        self.control_lock = control_lock
        self.server = server
        self.alive = True

    def close(self) -> None:
        self.alive = False
        try:
            self.listener.close()
        except Exception:
            pass
        with self.server.lock:
            if self.server.tunnels.get(self.port) is self:
                self.server.tunnels.pop(self.port, None)


class BoreServer:
    def __init__(self, min_port: int, max_port: int, secret: Optional[str], bind_addr: str,
                 bind_tunnels: str) -> None:
        self.min_port = min_port
        self.max_port = max_port
        self.secret = secret
        self.bind_addr = bind_addr
        self.bind_tunnels = bind_tunnels
        self.lock = threading.Lock()
        self.tunnels: Dict[int, Tunnel] = {}
        self.pending: Dict[str, PendingProxy] = {}
        self.shutdown = False

    def choose_listener(self, requested: int) -> Tuple[Optional[socket.socket], Optional[int], Optional[str]]:
        if requested != 0:
            if requested < self.min_port or requested > self.max_port:
                return None, None, "client port number not in allowed range"
            try:
                listener = bind_listener(self.bind_tunnels, requested)
                return listener, requested, None
            except OSError as e:
                if e.errno == errno.EADDRINUSE:
                    return None, None, "port already in use"
                return None, None, format_os_error(e)

        # Random port selection within the configured inclusive range.  Binding
        # port 0 is allowed by the original when the configured range contains 0;
        # the kernel-selected actual port is returned to the client.
        candidates = list(range(self.min_port, self.max_port + 1))
        random.shuffle(candidates)
        for cand in candidates[:10000]:  # avoid pathological huge loops
            try:
                listener = bind_listener(self.bind_tunnels, cand)
                actual = listener.getsockname()[1]
                if actual in self.tunnels:
                    listener.close()
                    continue
                return listener, actual, None
            except OSError:
                continue
        # If the range is huge and the first sample all failed, try a sequential
        # sweep as a last resort.
        if len(candidates) > 10000:
            for cand in range(self.min_port, self.max_port + 1):
                try:
                    listener = bind_listener(self.bind_tunnels, cand)
                    actual = listener.getsockname()[1]
                    if actual in self.tunnels:
                        listener.close()
                        continue
                    return listener, actual, None
                except OSError:
                    continue
        return None, None, "failed to find an available port"

    def serve_forever(self) -> None:
        try:
            control = bind_listener(self.bind_addr, CONTROL_PORT)
        except OSError as e:
            die_runtime(format_os_error(e))
        log("INFO", "bore_cli::server", "server listening", fields={"addr": self.bind_addr})
        try:
            while True:
                try:
                    conn, addr = control.accept()
                except OSError:
                    break
                t = threading.Thread(target=self.handle_control, args=(conn, addr), daemon=True)
                t.start()
        finally:
            try:
                control.close()
            except Exception:
                pass

    def handle_control(self, conn: socket.socket, addr: Tuple[Any, ...]) -> None:
        addr_s = f"{addr[0]}:{addr[1]}"
        span = ("control", {"addr": addr_s})
        log("INFO", "bore_cli::server", "incoming connection", span=span)
        try:
            msg = recv_json(conn)
            if not msg:
                return
            typ = msg.get("type")
            if typ == "hello":
                self.handle_hello(conn, addr, span, msg)
            elif typ == "proxy":
                self.handle_proxy(conn, addr, span, msg)
            else:
                # Unknown data on the control port: keep the behavior quiet.
                return
        except Exception as e:
            log("WARN", "bore_cli::server", "connection exited with error", span=span,
                fields={"err": format_os_error(e)})
            return
        finally:
            log("INFO", "bore_cli::server", "connection exited", span=span)
            try:
                conn.close()
            except Exception:
                pass

    def handle_hello(self, conn: socket.socket, addr: Tuple[Any, ...], span: Tuple[str, Dict[str, Any]],
                     msg: Dict[str, Any]) -> None:
        client_secret = msg.get("secret")
        requested = int(msg.get("port", 0))

        if self.secret is not None:
            if client_secret is None:
                log("WARN", "bore_cli::server", "server handshake failed", span=span,
                    fields={"err": "server requires secret, but no secret was provided"})
                send_json(conn, {"type": "error", "error": "server requires authentication, but no client secret was provided", "plain": True})
                return
            if client_secret != self.secret:
                log("WARN", "bore_cli::server", "server handshake failed", span=span,
                    fields={"err": "invalid secret"})
                send_json(conn, {"type": "error", "error": "invalid secret"})
                return
        else:
            # Observed behavior: providing a client secret to a server without a
            # secret does not complete the handshake; it simply waits until the
            # client disconnects.
            if client_secret is not None:
                while True:
                    data = conn.recv(4096)
                    if not data:
                        return

        listener, actual_port, err = self.choose_listener(requested)
        if err is not None or listener is None or actual_port is None:
            send_json(conn, {"type": "error", "error": err or "failed to bind port"})
            return

        lock = threading.Lock()
        tunnel = Tunnel(actual_port, self.bind_tunnels, listener, conn, addr, lock, self)
        with self.lock:
            self.tunnels[actual_port] = tunnel
        log("INFO", "bore_cli::server", "new client", span=span,
            fields={"host": self.bind_tunnels, "port": actual_port})
        send_json(conn, {"type": "ready", "port": actual_port}, lock)

        accept_thread = threading.Thread(target=self.accept_tunnel, args=(tunnel, span), daemon=True)
        accept_thread.start()

        # Keep the control connection open.  Any EOF tears down the tunnel.
        try:
            while True:
                data = conn.recv(4096)
                if not data:
                    break
        finally:
            tunnel.close()
            # Close pending external connections belonging to this tunnel.
            with self.lock:
                doomed = [pid for pid, p in self.pending.items() if p.tunnel is tunnel]
                for pid in doomed:
                    p = self.pending.pop(pid, None)
                    if p:
                        try:
                            p.external.close()
                        except Exception:
                            pass

    def accept_tunnel(self, tunnel: Tunnel, control_span: Tuple[str, Dict[str, Any]]) -> None:
        while tunnel.alive:
            try:
                external, ext_addr = tunnel.listener.accept()
            except OSError:
                break
            ext_s = f"{ext_addr[0]}:{ext_addr[1]}"
            log("INFO", "bore_cli::server", "new connection", span=control_span,
                fields={"addr": ext_s, "port": tunnel.port})
            pid = str(uuid.uuid4())
            with self.lock:
                self.pending[pid] = PendingProxy(external, ext_addr, tunnel)
            try:
                send_json(tunnel.control, {"type": "connect", "id": pid}, tunnel.control_lock)
            except Exception:
                with self.lock:
                    self.pending.pop(pid, None)
                try:
                    external.close()
                except Exception:
                    pass

    def handle_proxy(self, conn: socket.socket, addr: Tuple[Any, ...], span: Tuple[str, Dict[str, Any]],
                     msg: Dict[str, Any]) -> None:
        pid = str(msg.get("id", ""))
        # If the server is authenticated, proxy connections must carry the same
        # secret.  This is not normally user-visible, but prevents accidental
        # cross-talk between clients.
        if self.secret is not None and msg.get("secret") != self.secret:
            return
        with self.lock:
            pending = self.pending.pop(pid, None)
        if pending is None:
            return
        log("INFO", "bore_cli::server", "forwarding connection", span=span, fields={"id": pid})
        pipe_sockets(conn, pending.external)


# ---------------------------------------------------------------------------
# Client implementation


def connect_control(host: str) -> socket.socket:
    try:
        return socket.create_connection((host, CONTROL_PORT), timeout=10)
    except Exception as e:
        die_runtime(f"could not connect to {host}:{CONTROL_PORT}", format_os_error(e))


def run_local(local_host: str, to_host: str, remote_port: int, local_port: int,
              secret: Optional[str]) -> None:
    control = connect_control(to_host)
    hello: Dict[str, Any] = {"type": "hello", "port": remote_port}
    if secret is not None:
        hello["secret"] = secret
    try:
        send_json(control, hello)
        msg = recv_json(control)
    except Exception as e:
        die_runtime(f"could not connect to {to_host}:{CONTROL_PORT}", format_os_error(e))
    if not msg:
        # Match the observed hanging behavior as closely as possible: if the
        # server says nothing, block on the control connection until killed/EOF.
        while True:
            data = control.recv(4096)
            if not data:
                raise SystemExit(0)

    if msg.get("type") == "error":
        err = str(msg.get("error", "server error"))
        if msg.get("plain"):
            die_runtime(err)
        die_runtime(f"server error: {err}")
    if msg.get("type") != "ready":
        die_runtime("server error: invalid response")
    actual_port = int(msg.get("port", remote_port))
    log("INFO", "bore_cli::client", "connected to server", fields={"remote_port": actual_port})
    log("INFO", "bore_cli::client", f"listening at {to_host}:{actual_port}")

    try:
        while True:
            msg = recv_json(control)
            if msg is None:
                break
            if msg.get("type") == "connect":
                pid = str(msg.get("id"))
                t = threading.Thread(target=handle_client_proxy,
                                     args=(to_host, local_host, local_port, secret, pid), daemon=True)
                t.start()
    except KeyboardInterrupt:
        pass


def handle_client_proxy(to_host: str, local_host: str, local_port: int, secret: Optional[str], pid: str) -> None:
    span = ("proxy", {"id": pid})
    log("INFO", "bore_cli::client", "new connection", span=span)
    proxy: Optional[socket.socket] = None
    local: Optional[socket.socket] = None
    try:
        proxy = socket.create_connection((to_host, CONTROL_PORT), timeout=10)
        msg: Dict[str, Any] = {"type": "proxy", "id": pid}
        if secret is not None:
            msg["secret"] = secret
        send_json(proxy, msg)
        try:
            local = socket.create_connection((local_host, local_port), timeout=10)
        except Exception:
            log("WARN", "bore_cli::client", "connection exited with error", span=span,
                fields={"err": f"could not connect to {local_host}:{local_port}"})
            try:
                proxy.close()
            except Exception:
                pass
            return
        pipe_sockets(proxy, local)
        log("INFO", "bore_cli::client", "connection exited", span=span)
    except Exception as e:
        log("WARN", "bore_cli::client", "connection exited with error", span=span,
            fields={"err": format_os_error(e)})
    finally:
        for s in (proxy, local):
            if s is not None:
                try:
                    s.close()
                except Exception:
                    pass


# ---------------------------------------------------------------------------
# Socket copying


def pipe_sockets(a: socket.socket, b: socket.socket) -> None:
    done = threading.Event()

    def copy(src: socket.socket, dst: socket.socket) -> None:
        try:
            while not done.is_set():
                data = src.recv(65536)
                if not data:
                    break
                dst.sendall(data)
        except Exception:
            pass
        finally:
            done.set()
            try:
                dst.shutdown(socket.SHUT_WR)
            except Exception:
                pass
            try:
                src.shutdown(socket.SHUT_RD)
            except Exception:
                pass

    t1 = threading.Thread(target=copy, args=(a, b), daemon=True)
    t2 = threading.Thread(target=copy, args=(b, a), daemon=True)
    t1.start(); t2.start()
    while not done.is_set():
        time.sleep(0.01)
    # Give the opposite direction a brief chance to flush EOF.
    t1.join(timeout=1)
    t2.join(timeout=1)
    try:
        a.close()
    except Exception:
        pass
    try:
        b.close()
    except Exception:
        pass


# ---------------------------------------------------------------------------
# Argument parsing


def take_value(argv: List[str], i: int, opt: str, label: str) -> Tuple[str, int]:
    if i + 1 >= len(argv) or argv[i + 1] == "--" or argv[i + 1].startswith("-"):
        die2(f"a value is required for '{opt} {label}' but none was supplied")
    return argv[i + 1], i + 2


def duplicate(opt_label: str, usage: str) -> None:
    die2(f"the argument '{opt_label}' cannot be used multiple times", usage=usage)


def parse_local(argv: List[str]) -> None:
    p = prog_name()
    if any(a in ("-h", "--help") for a in argv):
        sys.stdout.write(local_help())
        return

    local_host = "localhost"
    to_host = os.environ.get("BORE_SERVER")
    remote_port_s = "0"
    secret = os.environ.get("BORE_SECRET") if "BORE_SECRET" in os.environ else None
    positional: List[str] = []
    seen: Dict[str, bool] = {}
    used_secret = False
    i = 0
    positional_mode = False
    while i < len(argv):
        a = argv[i]
        if positional_mode:
            positional.append(a)
            i += 1
            continue
        if a == "--":
            positional_mode = True
            i += 1
            continue
        if a in ("--local-host", "-l"):
            if seen.get("local-host"):
                duplicate("--local-host <HOST>", f"{p} local [OPTIONS] --to <TO> <LOCAL_PORT>")
            seen["local-host"] = True
            val, i = take_value(argv, i, "--local-host" if a == "--local-host" else "-l", "<HOST>")
            local_host = val
            continue
        if a.startswith("--local-host="):
            if seen.get("local-host"):
                duplicate("--local-host <HOST>", f"{p} local [OPTIONS] --to <TO> <LOCAL_PORT>")
            seen["local-host"] = True
            local_host = a.split("=", 1)[1]
            i += 1
            continue
        if a.startswith("-l="):
            if seen.get("local-host"):
                duplicate("--local-host <HOST>", f"{p} local [OPTIONS] --to <TO> <LOCAL_PORT>")
            seen["local-host"] = True
            local_host = a.split("=", 1)[1]
            i += 1
            continue
        if a in ("--to", "-t"):
            if seen.get("to"):
                duplicate("--to <TO>", f"{p} local [OPTIONS] --to <TO> <LOCAL_PORT>")
            seen["to"] = True
            val, i = take_value(argv, i, "--to" if a == "--to" else "-t", "<TO>")
            to_host = val
            continue
        if a.startswith("--to="):
            if seen.get("to"):
                duplicate("--to <TO>", f"{p} local [OPTIONS] --to <TO> <LOCAL_PORT>")
            seen["to"] = True
            to_host = a.split("=", 1)[1]
            i += 1
            continue
        if a.startswith("-t="):
            if seen.get("to"):
                duplicate("--to <TO>", f"{p} local [OPTIONS] --to <TO> <LOCAL_PORT>")
            seen["to"] = True
            to_host = a.split("=", 1)[1]
            i += 1
            continue
        if a in ("--port", "-p"):
            if seen.get("port"):
                duplicate("--port <PORT>", f"{p} local [OPTIONS] --to <TO> <LOCAL_PORT>")
            seen["port"] = True
            val, i = take_value(argv, i, "--port" if a == "--port" else "-p", "<PORT>")
            remote_port_s = val
            continue
        if a.startswith("--port="):
            if seen.get("port"):
                duplicate("--port <PORT>", f"{p} local [OPTIONS] --to <TO> <LOCAL_PORT>")
            seen["port"] = True
            remote_port_s = a.split("=", 1)[1]
            i += 1
            continue
        if a.startswith("-p="):
            if seen.get("port"):
                duplicate("--port <PORT>", f"{p} local [OPTIONS] --to <TO> <LOCAL_PORT>")
            seen["port"] = True
            remote_port_s = a.split("=", 1)[1]
            i += 1
            continue
        if a in ("--secret", "-s"):
            if seen.get("secret"):
                duplicate("--secret <SECRET>", f"{p} local [OPTIONS] --to <TO> <LOCAL_PORT>")
            seen["secret"] = True
            used_secret = True
            val, i = take_value(argv, i, "--secret" if a == "--secret" else "-s", "<SECRET>")
            secret = val
            continue
        if a.startswith("--secret="):
            if seen.get("secret"):
                duplicate("--secret <SECRET>", f"{p} local [OPTIONS] --to <TO> <LOCAL_PORT>")
            seen["secret"] = True
            used_secret = True
            secret = a.split("=", 1)[1]
            i += 1
            continue
        if a.startswith("-s="):
            if seen.get("secret"):
                duplicate("--secret <SECRET>", f"{p} local [OPTIONS] --to <TO> <LOCAL_PORT>")
            seen["secret"] = True
            used_secret = True
            secret = a.split("=", 1)[1]
            i += 1
            continue
        if a.startswith("-"):
            die2(f"unexpected argument '{a}' found", usage=f"{p} local [OPTIONS] --to <TO> <LOCAL_PORT>",
                 tip=f"to pass '{a}' as a value, use '-- {a}'")
        positional.append(a)
        i += 1

    if len(positional) > 1:
        extra = positional[1]
        die2(f"unexpected argument '{extra}' found", usage=f"{p} local [OPTIONS] --to <TO> <LOCAL_PORT>")

    local_port_s: Optional[str]
    if positional:
        local_port_s = positional[0]
    else:
        local_port_s = os.environ.get("BORE_LOCAL_PORT")

    missing: List[str] = []
    if to_host is None:
        missing.append("--to <TO>")
    if local_port_s is None:
        missing.append("<LOCAL_PORT>")
    if missing:
        sys.stderr.write("error: the following required arguments were not provided:\n")
        for m in missing:
            sys.stderr.write(f"  {m}\n")
        usage = f"{p} local --to <TO> "
        if used_secret:
            usage += "--secret <SECRET> "
        usage += "<LOCAL_PORT>"
        sys.stderr.write(f"\nUsage: {usage}\n\nFor more information, try '--help'.\n")
        raise SystemExit(2)

    remote_port = parse_u16(remote_port_s, "--port <PORT>")
    local_port = parse_u16(str(local_port_s), "<LOCAL_PORT>")
    run_local(local_host, str(to_host), remote_port, local_port, secret)


def parse_server(argv: List[str]) -> None:
    p = prog_name()
    if any(a in ("-h", "--help") for a in argv):
        sys.stdout.write(server_help())
