    min_s = os.environ.get("BORE_MIN_PORT", "1024")
    max_s = os.environ.get("BORE_MAX_PORT", "65535")
    secret = os.environ.get("BORE_SECRET") if "BORE_SECRET" in os.environ else None
    bind_addr = "0.0.0.0"
    bind_tunnels: Optional[str] = None
    seen: Dict[str, bool] = {}
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--":
            if i + 1 < len(argv):
                die2(f"unexpected argument '{argv[i+1]}' found", usage=f"{p} server [OPTIONS]")
